	}{
		{"init command", []string{"config", "init"}, 0},
		{"get with key", []string{"config", "get", "db.host"}, 0},
		{"set key value", []string{"config", "set", "db.host", "localhost"}, 0},
		{"delete key", []string{"config", "delete", "db.host"}, 0},
		{"validate config", []string{"config", "validate"}, 0},
		{"list all", []string{"config", "list"}, 0},
		{"unknown command", []string{"config", "bogus"}, 2},
		{"missing args for set", []string{"config", "set", "key"}, 2},
		{"no command", []string{"config"}, 2},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			exit := runCLI(tt.args)
			if exit != tt.wantExit {
				t.Errorf("got exit %d, want %d", exit, tt.wantExit)
			}
		})
	}
}

func TestFlags(t *testing.T) {
	tests := []struct {
		name     string
		args     []string
		wantExit int
	}{
		{"custom config path", []string{"config", "--config", "/tmp/test.yaml", "list"}, 0},
		{"json format", []string{"config", "--format", "json", "list"}, 0},
		{"yaml format", []string{"config", "--format", "yaml", "list"}, 0},
		{"quiet mode", []string{"config", "--quiet", "init"}, 0},
		{"verbose mode", []string{"config", "--verbose", "validate"}, 0},
		{"invalid format", []string{"config", "--format", "xml", "list"}, 2},
		{"combined flags", []string{"config", "--quiet", "--format", "json", "list"}, 0},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			exit := runCLI(tt.args)
			if exit != tt.wantExit {
				t.Errorf("got exit %d, want %d", exit, tt.wantExit)
			}
		})
	}
}

func TestOutputStreams(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantStdout string
		wantStderr string
	}{
		{"list outputs to stdout", []string{"config", "list"}, "key=", ""},
		{"error to stderr", []string{"config", "get", "nonexistent"}, "", "not found"},
		{"quiet suppresses stdout", []string{"config", "--quiet", "list"}, "", ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := captureOutput(tt.args)
			if tt.wantStdout != "" && !bytes.Contains(stdout, []byte(tt.wantStdout)) {
				t.Errorf("stdout missing %q", tt.wantStdout)
			}
			if tt.wantStderr != "" && !bytes.Contains(stderr, []byte(tt.wantStderr)) {
				t.Errorf("stderr missing %q", tt.wantStderr)
			}
		})
	}
}

func TestFileOperations(t *testing.T) {
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")

	tests := []struct {
		name     string
		args     []string
		setup    func()
		check    func() error
		wantExit int
	}{
		{
			name: "init creates file",
			args: []string{"config", "--config", configPath, "init"},
			check: func() error {
				_, err := os.Stat(configPath)
				return err
			},
			wantExit: 0,
		},
		{
			name:     "read missing file",
			args:     []string{"config", "--config", "/nonexistent/path.yaml", "list"},
			wantExit: 1,
		},
		{
			name: "permission denied",
			args: []string{"config", "--config", "/etc/shadow", "init"},
			wantExit: 1,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if tt.setup != nil {
				tt.setup()
			}
			exit := runCLI(tt.args)
			if exit != tt.wantExit {
				t.Errorf("got exit %d, want %d", exit, tt.wantExit)
			}
			if tt.check != nil {
				if err := tt.check(); err != nil {
					t.Errorf("check failed: %v", err)
				}
			}
		})
	}
}

func TestEdgeCases(t *testing.T) {
	tests := []struct {
		name     string
		args     []string
		wantExit int
	}{
		{"empty key", []string{"config", "get", ""}, 2},
		{"key with spaces", []string{"config", "set", "key with spaces", "val"}, 2},
		{"special chars in value", []string{"config", "set", "k", "val=with&special"}, 0},
		{"very long key", []string{"config", "get", string(make([]byte, 1000))}, 2},
		{"unicode key", []string{"config", "set", "键", "值"}, 0},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			exit := runCLI(tt.args)
			if exit != tt.wantExit {
				t.Errorf("got exit %d, want %d", exit, tt.wantExit)
			}
		})
	}
}
